[{"order":1,"type":"heading","text":"Conditional Test Execution in JUnit 5"},{"order":2,"type":"paragraph","text":"Conditional test execution in JUnit 5 allows developers to enable or disable tests based on specific operating systems, Java Runtime Environment (JRE) versions, system properties, or environment variables. This is crucial for writing robust cross-platform and environment-aware test suites."},{"order":3,"type":"subheading","text":"1. Operating System Conditions"},{"order":4,"type":"paragraph","text":"You can run or skip tests depending on the host operating system using the @EnabledOnOs and @DisabledOnOs annotations."},{"order":5,"type":"code","text":"import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledOnOs;
import org.junit.jupiter.api.condition.DisabledOnOs;
import org.junit.jupiter.api.condition.OS;

class OsConditionalTest {

    @Test
    @EnabledOnOs(OS.WINDOWS)
    void onlyOnWindows() {
        // This test runs only on Windows
    }

    @Test
    @DisabledOnOs(OS.LINUX)
    void notOnLinux() {
        // This test runs on all OS except Linux
    }
}"},{"order":6,"type":"subheading","text":"2. JRE Version Conditions"},{"order":7,"type":"paragraph","text":"JUnit 5 provides @EnabledOnJre, @DisabledOnJre, and range-based annotations like @EnabledForJreRange to target specific Java versions."},{"order":8,"type":"code","text":"import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledOnJre;
import org.junit.jupiter.api.condition.JRE;
import org.junit.jupiter.api.condition.EnabledForJreRange;

class JreConditionalTest {

    @Test
    @EnabledOnJre(JRE.JAVA_17)
    void onlyOnJava17() {
        // Runs exclusively on Java 17
    }

    @Test
    @EnabledForJreRange(min = JRE.JAVA_11, max = JRE.JAVA_21)
    void runsOnJavaRange() {
        // Runs on Java versions 11 through 21 inclusive
    }
}"},{"order":9,"type":"subheading","text":"3. System Property Conditions"},{"order":10,"type":"paragraph","text":"Use @EnabledIfSystemProperty and @DisabledIfSystemProperty to execute tests based on JVM system properties."},{"order":11,"type":"code","text":"import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;

class SystemPropertyConditionalTest {

    @Test
    @EnabledIfSystemProperty(named = "os.arch", matches = ".*64.*")
    void onlyOn64BitArchitectures() {
        // Runs if the system architecture contains 64
    }
}"},{"order":12,"type":"subheading","text":"4. Environment Variable Conditions"},{"order":13,"type":"paragraph","text":"You can evaluate environment variables using @EnabledIfEnvironmentVariable and @DisabledIfEnvironmentVariable."},{"order":14,"type":"code","text":"import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;

class EnvironmentVariableConditionalTest {

    @Test
    @EnabledIfEnvironmentVariable(named = "ENV", matches = "CI")
    void onlyInCiEnvironment() {
        // Runs only when the ENV environment variable is set to CI
    }
}"},{"order":15,"type":"subheading","text":"Summary of Best Practices"},{"order":16,"type":"bullet_point","text":"Use built-in annotations like @EnabledOnOs instead of writing custom conditional logic inside test bodies."},{"order":17,"type":"bullet_point","text":"Combine multiple conditions carefully to prevent tests from accidentally being skipped across all developer workstations."},{"order":18,"type":"bullet_point","text":"Ensure regex patterns supplied to the 'matches' attribute are properly escaped."}]
